import{_ as t,o as a,c as s,a3 as i}from"./chunks/framework.BTQ4eCVb.js";const u=JSON.parse('{"title":"Tenant API v1 — AI Assistant","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Tenant API v1 — AI Assistant | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/api/tenant-v1-ai"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Tenant API v1 — AI Assistant | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/api/tenant-v1-ai"}]]},"headers":[],"relativePath":"api/tenant-v1-ai.md","filePath":"api/tenant-v1-ai.md","lastUpdated":1787850471000}'),o={name:"api/tenant-v1-ai.md"};function n(d,e,r,c,l,p){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="tenant-api-v1-—-ai-assistant" tabindex="-1">Tenant API v1 — AI Assistant <a class="header-anchor" href="#tenant-api-v1-—-ai-assistant" aria-label="Permalink to &quot;Tenant API v1 — AI Assistant&quot;">​</a></h1><p>Base path: <code>/api/tenant/v1</code></p><p>Middleware: <code>auth:tenant-api</code>, <code>tenant.user</code>, <code>not.suspended</code>, <code>verified</code>, <code>module:ai</code>, plus Spatie permissions noted per route.</p><p>Billing: Platform mode burns wallet credits (HTTP <strong>402</strong> when insufficient). BYOK uses the tenant provider key and does not debit the wallet.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ai.use</code></td><td>Conversations, messages, credits summary, Lead Copilot</td></tr><tr><td><code>ai.confirm</code></td><td>Confirm or cancel pending write actions</td></tr><tr><td><code>ai.manage</code></td><td>Update/test workspace AI settings (<code>PUT /settings</code> AI keys, <code>POST /settings/test-ai</code>)</td></tr></tbody></table><h2 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h2><h3 id="get-ai-credits" tabindex="-1">GET <code>/ai/credits</code> <a class="header-anchor" href="#get-ai-credits" aria-label="Permalink to &quot;GET `/ai/credits`&quot;">​</a></h3><p>Requires <code>ai.use</code>. Runs <code>ensurePeriod()</code> then returns dual-balance wallet summary and recent ledger entries.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;included_remaining&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">275</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;prepaid_balance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;available&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1275</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;period_ym&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-08&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;recent_ledger&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="conversations" tabindex="-1">Conversations <a class="header-anchor" href="#conversations" aria-label="Permalink to &quot;Conversations&quot;">​</a></h2><h3 id="get-ai-conversations" tabindex="-1">GET <code>/ai/conversations</code> <a class="header-anchor" href="#get-ai-conversations" aria-label="Permalink to &quot;GET `/ai/conversations`&quot;">​</a></h3><p>List current user&#39;s conversations (newest first). Requires <code>ai.use</code>.</p><p>Query: <code>limit</code> (default 20).</p><h3 id="post-ai-conversations" tabindex="-1">POST <code>/ai/conversations</code> <a class="header-anchor" href="#post-ai-conversations" aria-label="Permalink to &quot;POST `/ai/conversations`&quot;">​</a></h3><p>Create a conversation. Body: optional <code>context</code> object (page/module hints).</p><h3 id="get-ai-conversations-conversation" tabindex="-1">GET <code>/ai/conversations/{conversation}</code> <a class="header-anchor" href="#get-ai-conversations-conversation" aria-label="Permalink to &quot;GET `/ai/conversations/{conversation}`&quot;">​</a></h3><p>Fetch conversation with messages. Scoped to the authenticated user; foreign workspace IDs → <strong>404</strong>.</p><h3 id="post-ai-conversations-conversation-messages" tabindex="-1">POST <code>/ai/conversations/{conversation}/messages</code> <a class="header-anchor" href="#post-ai-conversations-conversation-messages" aria-label="Permalink to &quot;POST `/ai/conversations/{conversation}/messages`&quot;">​</a></h3><p>Send a user message and receive structured assistant output.</p><p>Body:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;What should I focus on today?&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;context&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;module&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tasks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Success payload includes:</p><ul><li><code>structured.answer</code>, <code>structured.insights</code>, <code>structured.suggested_actions</code>, <code>structured.references</code></li><li><code>usage</code> token counts and <code>credits_burned</code> (platform mode)</li><li><code>recent_messages</code> (latest user + assistant turns)</li></ul><p>Errors:</p><table tabindex="0"><thead><tr><th>Code</th><th>When</th></tr></thead><tbody><tr><td><strong>402</strong></td><td>Platform wallet empty or below pre-provider credit ceiling (<code>insufficient_ai_credits</code>)</td></tr><tr><td><strong>429</strong></td><td>AI route rate limit (<code>throttle:ai</code>)</td></tr><tr><td><strong>503</strong></td><td>AI disabled platform-wide or module not entitled</td></tr><tr><td><strong>422</strong></td><td>Validation</td></tr></tbody></table><h2 id="pending-write-actions" tabindex="-1">Pending write actions <a class="header-anchor" href="#pending-write-actions" aria-label="Permalink to &quot;Pending write actions&quot;">​</a></h2><p>Low-risk writes (for example <code>create_task</code>) create a pending row first.</p><h3 id="post-ai-actions-action-confirm" tabindex="-1">POST <code>/ai/actions/{action}/confirm</code> <a class="header-anchor" href="#post-ai-actions-action-confirm" aria-label="Permalink to &quot;POST `/ai/actions/{action}/confirm`&quot;">​</a></h3><p>Requires <code>ai.confirm</code>. Executes the tool (also requires underlying domain permission, e.g. <code>tasks.create</code>).</p><h3 id="post-ai-actions-action-cancel" tabindex="-1">POST <code>/ai/actions/{action}/cancel</code> <a class="header-anchor" href="#post-ai-actions-action-cancel" aria-label="Permalink to &quot;POST `/ai/actions/{action}/cancel`&quot;">​</a></h3><p>Requires <code>ai.confirm</code>. Marks pending action cancelled.</p><h2 id="lead-copilot" tabindex="-1">Lead Copilot <a class="header-anchor" href="#lead-copilot" aria-label="Permalink to &quot;Lead Copilot&quot;">​</a></h2><p>Requires <code>ai.use</code> and <code>view</code> policy on the lead.</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td>POST</td><td><code>/ai/leads/{lead}/summarize</code></td><td>One-paragraph overview + themes</td></tr><tr><td>POST</td><td><code>/ai/leads/{lead}/next-action</code></td><td>Recommended next step</td></tr><tr><td>POST</td><td><code>/ai/leads/{lead}/draft-follow-up</code></td><td>Draft message; body <code>channel</code>: <code>general</code> | <code>email</code> | <code>whatsapp</code></td></tr></tbody></table><p>Responses mirror conversation message structured output + <code>usage</code>.</p><h2 id="agent-tools-server-side" tabindex="-1">Agent tools (server-side) <a class="header-anchor" href="#agent-tools-server-side" aria-label="Permalink to &quot;Agent tools (server-side)&quot;">​</a></h2><p>Tools are not direct HTTP endpoints. The registry exposes them to the agent when module + permission gates pass:</p><p><strong>Leads</strong> (<code>leads.view</code>): <code>search_leads</code>, <code>get_lead</code>, <code>get_stale_leads</code>, <code>get_recent_lead_activity</code></p><p><strong>Tasks</strong> (<code>tasks.view</code> / <code>tasks.create</code>): <code>search_tasks</code>, <code>get_my_tasks</code>, <code>get_overdue_tasks</code>, <code>get_tasks_due_today</code>, <code>create_task</code> (pending confirmation)</p><p><strong>Projects</strong> (<code>projects.view</code>): <code>search_projects</code>, <code>get_project</code>, <code>get_overdue_projects</code></p><p><strong>Opportunities</strong> (<code>opportunities.view</code>): <code>search_opportunities</code>, <code>get_pipeline_summary</code></p><p><strong>Invoices</strong> (<code>invoices.view</code>): <code>get_overdue_invoices</code>, <code>get_invoice_balance_summary</code></p><p>Tool list/detail rows expose numeric <code>id</code> (SPA paths) and <code>uuid</code> (lookups). See <a href="/developer-guide/ai-tools">AI tools guide</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/architecture/ai-platform">AI platform architecture</a></li><li><a href="/developer-guide/ai-credits">AI credits</a></li><li><a href="/user-guide/ai-assistant">AI Assistant user guide</a></li></ul>',46)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
